import { cacheTag } from 'next/cache'

// Stand-in for the upstream ERP/PIM system. A sync run mutates this
// so subsequent cache recomputes pick up the "latest" catalog data.
let products = [
  { id: 1, name: 'Laptop', price: 999 },
  { id: 2, name: 'Phone', price: 699 },
  { id: 3, name: 'Tablet', price: 499 },
  { id: 4, name: 'Headphones', price: 199 },
  { id: 5, name: 'Watch', price: 299 },
]

export async function getAllProducts() {
  'use cache'
  cacheTag('products')

  // Simulate database delay
  await new Promise((resolve) => setTimeout(resolve, 100))

  return products
}

export async function syncCatalogFromErp() {
  // Simulate a slow bulk pull from the upstream ERP/PIM system touching
  // thousands of SKUs (pricing, inventory, availability).
  await new Promise((resolve) => setTimeout(resolve, 2000))

  products = products.map((product) => ({
    ...product,
    price: Math.round(product.price * (0.9 + Math.random() * 0.2)),
  }))
}

