import { after } from 'next/server'
import { updateTag } from 'next/cache'
import { getAllProducts, syncCatalogFromErp } from '@/lib/db'

export default async function Page() {
  const products = await getAllProducts()

  async function syncCatalog() {
    'use server'

    // Defer the slow ERP/PIM pull (and the resulting cache invalidation)
    // until after the response is sent, so the admin isn't stuck waiting
    // for thousands of SKUs to sync before they can keep working.
    after(async () => {
      await syncCatalogFromErp()
      updateTag('products')
    })
  }

  return (
    <div>
      <h1>Product Catalog</h1>

      <form action={syncCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>

      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id}>
              <td>{product.name}</td>
              <td>${product.price}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

